def _function_permissions_present(FunctionName, Permissions, region, key,
    keyid, profile):
    ret = {'result': True, 'comment': '', 'changes': {}}
    curr_permissions = __salt__['boto_lambda.get_permissions'](FunctionName,
        region=region, key=key, keyid=keyid, profile=profile)['permissions']
    need_update = False
    diffs = salt.utils.compare_dicts(curr_permissions, Permissions or {})
    if bool(diffs):
        ret['comment'] = os.linesep.join([ret['comment'],
            'Function permissions to be modified'])
        if __opts__['test']:
            msg = 'Function {0} set to be modified.'.format(FunctionName)
            ret['comment'] = msg
            ret['result'] = None
            return ret
        for sid, diff in diffs.iteritems():
            if diff.get('old', '') != '':
                _r = __salt__['boto_lambda.remove_permission'](FunctionName
                    =FunctionName, StatementId=sid, region=region, key=key,
                    keyid=keyid, profile=profile)
                ret['changes'].setdefault('new', {}).setdefault('Permissions',
                    {})[sid] = {}
                ret['changes'].setdefault('old', {}).setdefault('Permissions',
                    {})[sid] = diff['old']
            if diff.get('new', '') != '':
                _r = __salt__['boto_lambda.add_permission'](FunctionName=
                    FunctionName, StatementId=sid, region=region, key=key,
                    keyid=keyid, profile=profile, **diff['new'])
                ret['changes'].setdefault('new', {}).setdefault('Permissions',
                    {})[sid] = diff['new']
                oldperms = ret['changes'].setdefault('old', {}).setdefault(
                    'Permissions', {})
                if sid not in oldperms:
                    oldperms[sid] = {}
            if not _r.get('updated'):
                ret['result'] = False
                ret['comment'] = 'Failed to update function: {0}.'.format(_r
                    ['error']['message'])
                ret['changes'] = {}
    return ret
